import os
import base64
import json
from google.cloud import vision

def extract_layout(payload, config=None):
    config = config or {}
    client = vision.ImageAnnotatorClient()
    if isinstance(payload, str) and os.path.isfile(payload):
        with open(payload, 'rb') as image_file:
            content = image_file.read()
        image = vision.Image(content=content)
    else:
        image = vision.Image(content=base64.b64decode(payload))
    response = client.document_text_detection(image=image)
    result = []
    for page in response.full_text_annotation.pages:
        for block in page.blocks:
            block_data = {
                'type': 'BLOCK',
                'bounding_box': [(vertex.x, vertex.y) for vertex in block.bounding_box.vertices],
                'confidence': block.confidence,
                'text': ''
            }
            for paragraph in block.paragraphs:
                for word in paragraph.words:
                    word_text = ''.join([symbol.text for symbol in word.symbols])
                    block_data['text'] += word_text + ' '
            block_data['text'] = block_data['text'].strip()
            result.append(block_data)
    return result
